<!DOCTYPE html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Client Dashboard | AppTasker</title><style>:root{--p:#5b6df8;--n:#101828;--m:#667085;--bg:#f5f7fb;--line:#e7eaf0}*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Inter,system-ui;color:var(--n)}.shell{max-width:1180px;margin:auto;padding:28px 18px}.top{display:flex;justify-content:space-between;align-items:center}.brand{font-size:22px;font-weight:900}.logout{padding:10px 13px;border:1px solid var(--line);background:white;border-radius:10px}.hero{margin:25px 0;padding:28px;border-radius:22px;background:linear-gradient(135deg,#17213a,#5b6df8);color:white}.hero h1{font-size:32px;margin:5px 0}.grid{display:grid;grid-template-columns:1.2fr .8fr;gap:16px}.card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:20px}.plans{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.plan{border:1px solid var(--line);padding:15px;border-radius:14px}.plan strong{font-size:23px}.input{width:100%;padding:12px;border:1px solid #d7dce5;border-radius:10px;margin:6px 0}.btn{width:100%;border:0;background:var(--p);color:#fff;padding:12px;border-radius:10px;font-weight:850;margin-top:8px}.row{display:flex;justify-content:space-between;gap:12px;padding:14px 0;border-bottom:1px solid #eee}.muted{color:var(--m);font-size:12px}.status{font-size:11px;font-weight:850;background:#eef1ff;color:#4459c5;padding:5px 8px;border-radius:99px}.msg{background:#ecfdf3;color:#087a48;padding:12px;border-radius:11px}@media(max-width:800px){.grid{grid-template-columns:1fr}.plans{grid-template-columns:1fr}.hero h1{font-size:26px}}</style></head><body><main class="shell"><header class="top"><div class="brand">A · AppTasker</div><form method="POST" action="{{ route('logout') }}">@csrf<button class="logout">Logout</button></form></header><section class="hero"><small>CLIENT WORKSPACE</small><h1>Grow your app with real task campaigns.</h1><p>Submit your app, choose a pla